/*
 * Native unit test for the audio-brain serial link (wled00/held/held_link.cpp), run by
 * `npm test` through tools/held-test.js. Feeds protocol lines from
 * held-electronics/docs/Held_Lighting_Serial_Messages.md and checks what the engine does.
 */
#include <cstdio>
#include <cstring>
#include <cmath>
#include <vector>
#include <string>
#include "../../wled00/held/held_core.cpp"
#include "../../wled00/held/held_expr.cpp"
#include "../../wled00/held/held_link.cpp"

using namespace held;

static int checks = 0, fails = 0;
#define CHECK(c) do { checks++; if (!(c)) { fails++; printf("FAIL line %d: %s\n", __LINE__, #c); } } while (0)

static void feed(Link& l, const char* s, uint32_t now) { for (; *s; s++) l.feed(*s, now); }

static bool hasEvent(Engine& e, uint8_t type) {
  for (uint8_t i = 0; i < e.eventCount(); i++) if (e.eventInfo(i).type == type) return true;
  return false;
}

static double originBrightness(Engine& e) {
  std::vector<hf> buf(3 * e.stripLeds(0));
  e.render(0, buf.data());
  return buf[0];  // red channel of LED 0 (the default origin)
}

int main() {
  // ---- COUNT: first one is adopted silently, later ones fire events; required sets numPieces
  {
    Engine e;
    Link l(e);
    feed(l, "COUNT 3 6\r\n", 10);
    CHECK(e.count() == 3 && e.mask() == 0x7);
    CHECK(e.eventCount() == 0);
    feed(l, "COUNT 4 6\n", 20);
    CHECK(e.count() == 4 && hasEvent(e, EV_PIECE_IN));
    e.clearEvents();
    feed(l, "COUNT 5 5\n", 30);
    CHECK((int)e.getParam(GRP_GLOBAL, Gp::numPieces).a == 5);
    CHECK(e.count() == 5 && hasEvent(e, EV_ALL_IN));
    CHECK(l.status().seated == 5 && l.status().required == 5);
    e.clearEvents();
    feed(l, "COUNT 2 5\n", 40);
    CHECK(hasEvent(e, EV_PIECE_OUT));
  }

  // ---- STORY START / END, and allInTrigger = "Story start"
  {
    Engine e;
    Link l(e);
    e.setParam(GRP_GLOBAL, Gp::allInTrigger, 1, 1, false);
    feed(l, "COUNT 5 6\n", 1);
    feed(l, "COUNT 6 6\n", 2);
    CHECK(!hasEvent(e, EV_ALL_IN) && hasEvent(e, EV_PIECE_IN));   // completing the pieces waits for the story
    feed(l, "STORY START 3\n", 3);
    CHECK(hasEvent(e, EV_ALL_IN) && l.status().story == 3 && l.status().storyPlaying);
    feed(l, "STORY END 3\n", 4);
    CHECK(hasEvent(e, EV_STORY_END) && !l.status().storyPlaying);
    e.setParam(GRP_GLOBAL, Gp::allInTrigger, 0, 0, false);
    e.clearEvents();
    feed(l, "STORY START 4\n", 5);
    CHECK(!hasEvent(e, EV_ALL_IN));                               // default mode: allIn comes from COUNT
  }

  // ---- BEAT: external clock, pulse at the origin, missed counter, timeout back to the internal clock
  {
    Engine e;
    e.setParam(GRP_AMBIENT, Am::enabled, 0, 0, false);
    e.setParam(GRP_GLOBAL, Gp::levelSmoothing, 0, 0, false);
    Link l(e);
    e.tick(0.02f);
    double before = originBrightness(e);
    feed(l, "BEAT 1 55.0 370 1091\n", 1000);
    CHECK(e.externalClock());
    e.tick(0.001f);
    double after = originBrightness(e);
    CHECK(after > before + 0.1);                                   // the lub peak lights the origin right away
    char reply[LINK_LINE_MAX];
    CHECK(l.popReply(reply, sizeof(reply)) && strncmp(reply, "LOG", 3) == 0);
    for (int i = 0; i < 100; i++) e.tick(0.02f);                   // 2 s without BEAT: no internal beats while synced
    double quiet = originBrightness(e);
    CHECK(std::fabs(quiet - before) < 1e-6);
    feed(l, "BEAT 2 55.0 370 1091\n", 2000);
    feed(l, "BEAT 5 56.0 368 1071\n", 3000);
    CHECK(l.status().beats == 3 && l.status().missed == 2 && l.status().beatN == 5);
    CHECK(std::fabs(l.status().bpm - 56.0f) < 1e-4 && l.status().dubMs == 368 && l.status().nextMs == 1071);
    l.poll(6500);
    CHECK(e.externalClock());                                      // 3.5 s < 4 s default timeout
    l.poll(7100);
    CHECK(!e.externalClock());
    CHECK(l.popReply(reply, sizeof(reply)) && strstr(reply, "own heartbeat"));
    e.setParam(GRP_GLOBAL, Gp::beatSync, 0, 0, false);
    feed(l, "BEAT 6 56.0 368 1071\n", 8000);
    CHECK(!e.externalClock() && l.status().beats == 4);           // still counted, not followed
  }

  // ---- robustness: unknown, malformed and over-long lines are ignored; PING answers PONG
  {
    Engine e;
    Link l(e);
    feed(l, "HELLO\nBEAT x 1 2 3\nCOUNT 3\nCOUNT 40 6\nSTORY MIDDLE 2\nBEAT 1 55 370\n\n\n", 1);
    CHECK(l.status().unknown == 6 && l.status().lines == 0 && !e.externalClock() && e.count() == 0);
    std::string longLine(200, 'x');
    feed(l, longLine.c_str(), 2);
    feed(l, "\nPING\n", 2);
    CHECK(l.status().unknown == 7 && l.status().lines == 1);
    char reply[LINK_LINE_MAX];
    CHECK(l.popReply(reply, sizeof(reply)) && strcmp(reply, "PONG") == 0);
    CHECK(!l.popReply(reply, sizeof(reply)));
    for (int i = 0; i < 10; i++) feed(l, "PING\n", 3);              // reply queue is bounded
    int n = 0;
    while (l.popReply(reply, sizeof(reply))) n++;
    CHECK(n == LINK_REPLY_MAX);
    CHECK(l.handleLine("COUNT 2 6  \r", 4) && e.count() == 2);      // direct injection (JSON "link") trims
    CHECK(strcmp(l.status().last, "COUNT 2 6") == 0);
  }

  printf("%s: %d checks, %d failed\n", fails ? "FAIL" : "ok", checks, fails);
  return fails ? 1 : 0;
}
